@tailwind components;
@tailwind utilities;

/* tldraw otherwise caps the style panel at 148px; only the context tab needs
   the extra width, the styling tab keeps tldraw's default proportions. */
.tlui-style-panel:has(.dg-node-card-menu--context) {
  width: min(20rem, calc(100vw - 1rem));
  max-width: min(20rem, calc(100vw - 1rem));
}

.accent-border-bottom {
  border-bottom: 2px solid var(--interactive-accent) !important;
}

/* Match core status bar icon items (Sync, editor mode) instead of the
   default .status-bar-item padding, which makes the bar taller. */
.status-bar-item.dg-help-menu-status-bar-item {
  padding: 0 var(--size-2-2);
}

.dg-h1 {
  @apply mb-4 text-3xl font-bold;
}
.dg-h2 {
  @apply mb-3 text-2xl font-bold;
}
.dg-h3 {
  @apply mb-2 text-xl font-semibold;
}
.dg-h4 {
  @apply mb-2 text-lg font-bold;
}

.dg-create-node-button {
  background: var(--interactive-accent);
  color: var(--text-on-accent);
  border: none;
  border-radius: 4px;
  padding: 6px 12px;
  font-size: 11px;
  cursor: pointer;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 0.2s ease;
}

.dg-create-node-button:hover {
  background: var(--interactive-accent-hover);
}

.dg-clickable-link {
  text-decoration: underline;
  cursor: pointer;
}

/* Hide internal discourse graph frontmatter keys (toggle via body.dg-hide-frontmatter-ids) */
body.dg-hide-frontmatter-ids .metadata-property[data-property-key="authorId" i],
body.dg-hide-frontmatter-ids
  .metadata-property[data-property-key="importedAssets" i],
body.dg-hide-frontmatter-ids

